# Generated by scripts/packaging/formula.ts in ome-labs/ome for each release; do not edit by hand.
class Ome < Formula
  desc "Private k-of-n multisig on Aztec with threshold viewing"
  homepage "https://ome.network"
  version "0.3.0"
  license "Apache-2.0"

  depends_on "node@24"

  on_macos do
    on_arm do
      url "https://github.com/ome-labs/ome/releases/download/v0.3.0/ome-0.3.0-darwin-arm64.tar.gz"
      sha256 "a0472852b9f764cc3887ade02c916c38fc1f333366214b018f22cc1ba6e53582"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/ome-labs/ome/releases/download/v0.3.0/ome-0.3.0-linux-x64.tar.gz"
      sha256 "b90e37594053b5f469d396414fe938e140e98973fad1a738624a7673590796e9"
    end
    on_arm do
      url "https://github.com/ome-labs/ome/releases/download/v0.3.0/ome-0.3.0-linux-arm64.tar.gz"
      sha256 "ab2c7d470de625f985dd1616a16693d5f515c855b3ad9a567e0bf27dad572959"
    end
  end

  def install
    libexec.install Dir["*"]
    # The daemon runs with Homebrew's Node, also when a login service starts it without PATH.
    inreplace libexec/"bin/omed", 'node_default=""', %Q(node_default="#{formula_opt_bin("node@24")}/node")
    bin.install_symlink libexec/"bin/ome", libexec/"bin/omed", libexec/"bin/ome-keeper"
  end

  def caveats
    <<~EOS
      Create a profile with:
        ome init
      Keep your keeper online while your laptop sleeps by running the daemon as a login service:
        ome daemon install-service
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/ome --version")
    assert_match version.to_s, shell_output("#{bin}/ome-keeper --version")
  end
end
